mapper.select:
select round(avg(sample.price), 2) as referencePrice, count(1) as sampleSize, sample.cityLabel as cityLabel from (
select candidate.self_play_price as price, substring(candidate.address_name, 1, locate('市', candidate.address_name)) as cityLabel from cms_topic base join cms_topic candidate on candidate.id != base.id and candidate.product_type = base.product_type and candidate.lifecycle = 3 and candidate.self_play_price is not null and candidate.self_play_price > 0 and locate('市', base.address_name) > 0 and locate('市', candidate.address_name) > 0 and substring(candidate.address_name, 1, locate('市', candidate.address_name)) = substring(base.address_name, 1, locate('市', base.address_name)) where base.id = #{topicId}
select ticket.price as price, substring(candidate.address_name, 1, locate('市', candidate.address_name)) as cityLabel from cms_topic base join cms_topic candidate on candidate.id != base.id and candidate.product_type = base.product_type and candidate.lifecycle = 3 and locate('市', base.address_name) > 0 and locate('市', candidate.address_name) > 0 and substring(candidate.address_name, 1, locate('市', candidate.address_name)) = substring(base.address_name, 1, locate('市', base.address_name)) join oms_ticket ticket on ticket.owner_type = 1 and ticket.owner_id = candidate.id and ticket.sub_type = 'guided' and ticket.price > 0 where base.id = #{topicId}
) sample group by sample.cityLabel
